24	/// Lower, emit, encode, and self-gate a MIR module into `.beam` bytes.
25	pub(super) fn assemble(module: &MirModule) -> Result<Vec<u8>, SelectError> {
26	    let mut builder = Builder::new(module);
27	    let execute = find_execute(module)?;
28	
29	    let mut bodies = Vec::with_capacity(module.functions.len() + 1);
30	    for (index, function) in module.functions.iter().enumerate() {
31	        let reference = FnRef(u32::try_from(index).unwrap_or(u32::MAX));
32	        let body = match function {
33	            MirFn::Templated {
34	                name,
35	                template,
36	                sig,
37	                ..
38	            } => {
39	                let arity =
40	                    u8::try_from(sig.params.len()).map_err(|_| SelectError::OutOfRange {
41	                        what: format!("`{name}` arity exceeds 255"),
42	                    })?;
43	                lower_shell(&mut builder, name, arity, template, reference, execute)?
44	            }
45	            MirFn::Flow(flow) => lower_flow(&mut builder, flow, reference)?,
46	        };
47	        bodies.push(body);
48	    }
49	
50	    let mut instructions = Vec::new();
51	    for body in &bodies {
52	        instructions.extend(emit_body(&mut builder, body)?);
53	    }
54	
55	    let exports = build_exports(&mut builder, module)?;
56	    let module_atom = builder.atom(&module.name.clone());
57	    let parts = builder.into_parts();
58	
59	    let parsed = ParsedModule {
60	        name: module_atom,
61	        atoms: parts.atoms,
62	        instructions,
63	        imports: parts.imports,
64	        exports,
65	        lambdas: parts.lambdas,
66	        literals: parts.literals,
67	        string_table: Vec::new(),
68	        line_info: Vec::new(),
69	    };
70	
71	    let bytes = encode_module(&parsed, &parts.atom_table)?;
72	    self_gate(&bytes, &parts.atom_table)?;
73	    Ok(bytes)
74	}
