141	/// An empty BIF registry — imports resolve to deferred targets, which
142	/// `validate_module` accepts (the same standalone-validation setup the BC-1
143	/// capstone used).
144	struct NoBifs;
145	
146	impl BifRegistry for NoBifs {
147	    fn lookup(&self, _module: Atom, _function: Atom, _arity: u8) -> Option<NativeEntry> {
148	        None
149	    }
150	}
