152	/// The BC-3 oracle: every emitted module must re-load and validate through all
153	/// five loader layers (`load_beam_chunks` → `resolve_imports` →
154	/// `validate_module`).
155	fn self_gate(bytes: &[u8], atom_table: &AtomTable) -> Result<(), SelectError> {
156	    let parsed = load_beam_chunks(bytes, atom_table)
157	        .map_err(|error| SelectError::Load(error.to_string()))?;
158	    let registry = ModuleRegistry::new();
159	    let (resolved, _report) = resolve_imports(&parsed, &registry, &NoBifs, &AllCapabilitiesPolicy);
160	    validate_module(&parsed, &resolved)
161	        .map_err(|error| SelectError::Validate(format!("{error:?}")))?;
162	    Ok(())
